"""Original immune-treatment mechanism and toxicity questions."""
from qbank_authoring import question,ref
rows=[]
def q(*args,**kwargs):rows.append(question(*args,**kwargs))
IC=ref('SITC immune checkpoint inhibitor adverse-event guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC8237720/')
EN=ref('European Society of Endocrinology ICI endocrine guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC9641795/')
ES=ref('ESMO immunotherapy toxicity guideline','https://www.annalsofoncology.org/article/S0923-7534%2822%2904187-4/fulltext')
CA=ref('ASTCT consensus grading of CRS and neurological toxicity','https://doi.org/10.1016/j.bbmt.2018.12.758')

q('What is the principal antitumor rationale for blocking PD-1 or PD-L1?', 'Release an inhibitory immune-checkpoint signal that can restrain antitumor T-cell activity',[
 ('Directly cross-link tumor DNA as a platinum compound','Checkpoint antibodies act through immune regulation, not this cytotoxic mechanism.'),('Remove all regulatory control selectively from tumor cells alone','Immune effects also involve normal tissues and can cause toxicity.'),('Supply a cytotoxic payload through a cleavable antibody linker','That describes an antibody–drug conjugate.')],
 'Restoring immune activity can also disturb tolerance','**PD-1/PD-L1 blockade reduces an inhibitory signaling interaction.**',['Responses depend on tumor and host factors.','Benefit is not universal even when a biomarker is favorable.'],'**Anticipate immune-mediated toxicity across multiple organs.**',['Educate patients to report new symptoms early.','Do not assume a late event cannot be treatment-related.'],[['Target','Inhibitory checkpoint'],['Desired effect','Antitumor immunity'],['Risk','Immune injury to normal tissue']],[ref('NCI immune checkpoint inhibitors','https://www.cancer.gov/about-cancer/treatment/types/immunotherapy/checkpoint-inhibitors')])

q('Which distinction between CAR T cells and a T-cell-engaging bispecific antibody is most accurate?', 'CAR T therapy administers engineered T cells; a bispecific antibody can link a patient’s T cells to a tumor-associated target',[
 ('Both necessarily require the identical autologous cell-manufacturing process','A bispecific antibody is a drug product rather than the same engineered-cell product.'),('Bispecific antibodies act only by blocking estrogen synthesis','Their T-cell-engaging mechanism is different.'),('CAR T cells are simply platinum drugs attached to an antibody','They are living engineered immune cells.')],
 'Cell products and molecular bridges can share immune toxicities','**Both approaches can activate T cells against a target-bearing malignant population.**',['Targets and eligibility are disease- and product-specific.','CRS and neurological toxicity require organized monitoring pathways.'],'**Apply the specific product protocol rather than assuming class equivalence.**',['Assess infection and baseline organ risks.','Ensure access to appropriate acute management.'],[['CAR T','Engineered cellular product'],['T-cell bispecific','Molecular bridge'],['Shared concern','CRS/neurological toxicity']],[ref('NCI CAR T-cell therapy overview','https://www.cancer.gov/about-cancer/treatment/research/car-t-cells'),CA])

q('After CAR T infusion, a patient develops fever, hypotension requiring one vasopressor and low-flow oxygen requirement. Which assessment best reflects ASTCT CRS grading?', 'Grade 3 CRS on the basis of the vasopressor requirement, while evaluating infection and other causes',[
 ('Grade 1 because fever is the first symptom','Grade is determined by the most severe qualifying hypotension or hypoxia.'),('Grade 2 because the oxygen requirement is only low-flow','The more severe vasopressor domain determines the grade.'),('Grade 4 solely because any vasopressor is used','Grade 4 hypotension requires multiple vasopressors, excluding vasopressin in the consensus definition.')],
 'Use the most severe qualifying physiological domain','**CRS grading incorporates fever, hypotension and hypoxia not attributable to another cause.**',['One vasopressor with or without vasopressin fits grade 3 hypotension.','Concurrent sepsis remains possible and needs parallel assessment.'],'**Escalate monitoring and protocol-based treatment promptly.**',['Provide hemodynamic and respiratory support.','Use product-specific cytokine-directed and steroid guidance.'],[['Low-flow oxygen alone','Grade 2 hypoxia domain'],['One vasopressor','Grade 3 hypotension domain'],['Overall grade','Highest qualifying domain']],[CA],style='clinical_scenario')

q('Which agent directly targets the IL-6 receptor and is used for appropriate cytokine-release syndrome after immune-effector therapy?', 'Tocilizumab',[
 ('Infliximab','This targets TNF rather than the IL-6 receptor.'),('Rituximab','This targets CD20.'),('Trastuzumab','This targets HER2.')],
 'Cytokine-directed treatment supplements physiological support','**IL-6 receptor blockade is central to many CRS treatment protocols.**',['Indications and timing depend on severity and product guidance.','Steroids can also be required.'],'**Continue evaluating infection and organ dysfunction.**',['Tocilizumab is not a substitute for sepsis management when infection is possible.','Do not extrapolate its CRS role to isolated ICANS.'],[['Tocilizumab','IL-6 receptor'],['Infliximab','TNF'],['Rituximab','CD20']],[CA,ref('FDA tocilizumab prescribing information','https://www.gene.com/download/pdf/actemra_prescribing.pdf')])

q('A patient develops aphasia and impaired attention after CAR T therapy, without active CRS. Which treatment principle is most appropriate for clinically significant ICANS?', 'Use severity-guided corticosteroids and neurological assessment; tocilizumab alone is not the treatment for isolated ICANS',[
 ('Give tocilizumab alone because every neurological symptom is driven by peripheral IL-6','Isolated ICANS requires a different treatment approach.'),('Exclude ICANS whenever brain CT is normal','Imaging can be normal despite clinically important neurotoxicity.'),('Assume aphasia is expected and postpone stroke or seizure assessment','Alternative neurological emergencies must be evaluated promptly.')],
 'Neurological toxicity can occur independently of active CRS','**ICANS is a clinical syndrome requiring structured neurological assessment.**',['Evaluate seizures, stroke, infection and metabolic causes.','ICE testing contributes to grading but does not replace the full examination.'],'**Use the immune-effector protocol and urgent specialist support.**',['Monitor airway and consciousness in severe disease.','Treat concurrent CRS separately if present.'],[['Isolated ICANS','Steroid-based protocol'],['Assessment','ICE plus neurological domains'],['Differential','Stroke, seizure, infection, metabolic causes']],[CA],style='clinical_scenario')

q('A patient receiving a PD-1 inhibitor develops cough, dyspnea and new bilateral ground-glass opacities. What is the best initial framing?', 'Assess for immune pneumonitis while evaluating infection, embolism and tumor-related causes, and hold treatment when clinically indicated',[
 ('The CT pattern alone proves immune pneumonitis','Imaging overlaps with infection and other processes.'),('A normal eosinophil count excludes immune toxicity','Eosinophilia is not required.'),('Continue treatment unchanged despite progressive hypoxemia','Clinically important toxicity requires urgent assessment and treatment interruption.')],
 'An immune diagnosis does not remove competing emergencies','**Checkpoint pneumonitis is a diagnosis requiring clinical and radiological assessment and exclusion of alternatives.**',['Severity determines steroid route, dose and admission needs.','Microbiological evaluation and selected bronchoscopy can be important.'],'**Treat significant hypoxemia promptly and coordinate oncology and respiratory care.**',['Use severity-guided corticosteroids when immune pneumonitis is likely.','Consider infection prevention and monitoring during prolonged immunosuppression.'],[['Possible irAE','Pneumonitis'],['Mimics','Infection/embolism/progression'],['Severity','Guides admission and immunosuppression']],[IC,ES],style='clinical_scenario')

q('Soon after combination checkpoint therapy, a patient has ptosis, proximal weakness, elevated creatine kinase and troponin. Which dangerous overlap should be suspected?', 'Immune myositis, myocarditis and myasthenic features',[
 ('Isolated uncomplicated hypothyroidism as the complete explanation','The cardiac and neuromuscular combination raises a more urgent concern.'),('A benign exercise-related CK rise requiring no cardiac assessment','Troponin elevation and weakness after ICI require urgent review.'),('Routine delayed chemotherapy alopecia','This does not explain the findings.')],
 'Several high-risk immune toxicities can present together','**Myocarditis can overlap with myositis and myasthenic syndromes.**',['Respiratory muscle weakness and conduction disease may deteriorate rapidly.','A preserved ejection fraction does not exclude myocarditis.'],'**Hold ICI and arrange urgent monitored multidisciplinary care.**',['Assess ECG, cardiac biomarkers and respiratory mechanics.','Start appropriate early immunosuppression when myocarditis is considered likely.'],[['Muscle','CK/weakness'],['Heart','Troponin/conduction risk'],['Neuromuscular junction','Ptosis/bulbar/respiratory weakness']],[IC,ref('ESC cardio-oncology guideline','https://doi.org/10.1093/eurheartj/ehac244')],style='clinical_scenario')

q('A patient on checkpoint therapy has hypotension, hyponatremia, low morning cortisol and low ACTH, with low free T4. Which treatment sequence is safest?', 'Provide glucocorticoid treatment before starting thyroid-hormone replacement',[
 ('Start levothyroxine first and postpone glucocorticoids','Thyroid replacement can precipitate crisis in untreated cortisol deficiency.'),('Give fludrocortisone alone for presumed isolated mineralocorticoid loss','Low ACTH suggests central adrenal insufficiency, in which aldosterone is usually preserved.'),('Wait for pituitary MRI before treating hemodynamic instability','Urgent treatment of possible adrenal crisis must not wait.')],
 'Replace the life-preserving deficient axis first','**ICI hypophysitis can cause ACTH deficiency and central hypothyroidism.**',['Draw appropriate blood samples if this does not delay treatment.','Acute crisis requires stress-dose glucocorticoids and resuscitation.'],'**Stabilize cortisol replacement before adding thyroid hormone.**',['Free T4 rather than TSH guides central hypothyroid replacement.','High-dose immunosuppression is not routinely needed for uncomplicated hypophysitis without compression.'],[['Low cortisol/low ACTH','Central adrenal insufficiency'],['First replacement','Glucocorticoid'],['Thyroid monitoring','Free T4 in central disease']],[EN],style='clinical_scenario')

q('Transient thyrotoxicosis followed by hypothyroidism occurs during checkpoint therapy, with evidence of destructive thyroiditis rather than Graves disease. Which approach is most appropriate?', 'Treat symptoms during the thyrotoxic phase and provide thyroid replacement if persistent hypothyroidism develops',[
 ('Use long-term antithyroid synthesis blockade for every destructive thyroiditis','Stored hormone release, not sustained excess synthesis, drives the usual initial phase.'),('Perform radioiodine ablation immediately in every case','This is not the routine response to destructive thyroiditis.'),('Stop all anticancer treatment permanently for any biochemical thyroid abnormality','Stable endocrine replacement often allows continued or resumed ICI.')],
 'Release of stored hormone differs from overproduction','**Destructive thyroiditis often evolves through hyperthyroid and hypothyroid phases.**',['A beta blocker can help symptomatic thyrotoxicosis when appropriate.','Persistent or atypical thyrotoxicosis requires assessment for Graves disease and other causes.'],'**Monitor the trajectory and treat the demonstrated dysfunction.**',['Assess cortisol when clinically indicated before thyroid replacement.','Coordinate endocrine and oncology care.'],[['Destructive phase','Stored hormone release'],['Symptoms','Selected beta blockade'],['Later hypothyroidism','Replacement when indicated']],[EN],style='clinical_scenario')

q('A checkpoint-treated patient presents with hyperglycemia, ketonemia and metabolic acidosis. Which statement about ICI-associated diabetes is correct?', 'It can reflect rapid insulin deficiency and requires immediate DKA treatment and ongoing insulin assessment',[
 ('A modest HbA1c excludes the diagnosis','Rapid onset may precede a markedly elevated HbA1c.'),('High-dose steroids reliably restore beta-cell function and replace insulin','Steroids are not a reliable reversal strategy and can worsen hyperglycemia.'),('DKA can wait until pancreatic autoantibody results return','Emergency treatment must begin without waiting.')],
 'A new endocrine irAE can be a metabolic emergency','**ICI-associated diabetes can cause abrupt severe insulin deficiency.**',['C-peptide and autoantibodies help characterize the process but should not delay care.','Other causes of diabetes and hyperglycemia remain possible.'],'**Treat DKA using current fluid, electrolyte and insulin guidance.**',['Arrange long-term insulin education and endocrine follow-up.','Assess other endocrine toxicity when clinically indicated.'],[['Acute problem','DKA'],['Mechanism','Insulin deficiency possible'],['HbA1c','May underrepresent abrupt onset']],[EN],style='clinical_scenario')

q('A patient develops frequent bloody diarrhea on checkpoint therapy. What is the best initial management principle?', 'Assess severity and infectious causes, hold ICI when indicated and treat likely immune colitis with severity-guided immunosuppression',[
 ('Give an antimotility drug alone despite systemic illness and bleeding','Severe colitis requires evaluation and specific treatment.'),('Assume every episode is immune-mediated without stool assessment','Infection can mimic or coexist with immune colitis.'),('Continue ICI until bowel perforation confirms the diagnosis','That delays management of potentially serious toxicity.')],
 'Inflammation and infection need parallel consideration','**Immune colitis can cause serious dehydration, bleeding and perforation.**',['Stool testing and selected endoscopy help establish severity and exclude mimics.','Steroid-refractory disease may require infliximab or vedolizumab after appropriate assessment.'],'**Escalate promptly when severe or not responding.**',['Assess for complications and admission needs.','Screen for relevant infections before biologic immunosuppression when feasible.'],[['Evaluation','Severity and infection'],['Initial immune treatment','Corticosteroids when indicated'],['Refractory disease','Selected biologic therapy']],[IC,ES],style='clinical_scenario')

q('Which additional immunosuppressant is commonly considered for steroid-refractory immune hepatitis, while infliximab is generally avoided because of hepatic concerns?', 'Mycophenolate mofetil',[
 ('Infliximab as the default in all immune hepatitis','It is generally avoided in this setting because of hepatotoxicity concerns.'),('Tocilizumab as the mandatory first treatment for every transaminase rise','This is not the standard first-line hepatitis pathway.'),('Methimazole','This inhibits thyroid hormone synthesis, not immune hepatitis.')],
 'The affected organ changes the rescue strategy','**Immune-hepatitis treatment differs from the biologic pathway used for colitis.**',['Exclude viral, obstructive, metastatic and drug-related alternatives.','Severity and response guide steroid and second-line treatment.'],'**Seek specialist input for severe or steroid-refractory disease.**',['Consider biopsy when the diagnosis is uncertain or the course is atypical.','Monitor synthetic function as well as aminotransferases.'],[['First assessment','Alternative liver causes'],['Refractory immune hepatitis','Mycophenolate often considered'],['Infliximab','Generally avoided']],[IC,ES])

q('A patient on ICI develops AKI while also taking a proton-pump inhibitor and after several days of diarrhea. Which interpretation is best?', 'Immune interstitial nephritis is possible, but volume depletion, obstruction and other nephrotoxic or interstitial-nephritis causes must be assessed',[
 ('Any creatinine rise on ICI proves immune nephritis','Several competing mechanisms are common.'),('Sterile pyuria uniquely identifies checkpoint nephritis','It is neither sufficiently sensitive nor specific.'),('A kidney biopsy can never affect management','Selected cases benefit from pathological clarification.')],
 'An exposure association is not a complete renal diagnosis','**ICI-associated AKI often involves interstitial nephritis, but the differential remains broad.**',['Review concomitant medicines and fluid losses.','Urinalysis, protein assessment and imaging are chosen according to the presentation.'],'**Coordinate oncology and nephrology for severity-guided management.**',['Hold the implicated treatment when appropriate.','Use biopsy and immunosuppression selectively based on the clinical situation.'],[['Prerenal','Diarrhea/volume loss'],['Interstitial injury','ICI or another medicine'],['Assessment','Cause and severity']],[IC],style='clinical_scenario')

q('Which statement about timing of immune-related adverse events is correct?', 'They may occur during treatment or after treatment has stopped',[
 ('They are restricted to the first infusion day','That timing is more typical of some infusion reactions, not all irAEs.'),('They cannot occur after the last dose has cleared from plasma','Immune effects can persist beyond simple drug-exposure timing.'),('Any symptom months later must automatically be immune-mediated','Delayed toxicity is possible, but alternative causes still require assessment.')],
 'Immune effects can outlast administration','**The temporal window for irAEs is broader than an immediate infusion reaction.**',['Different organs have different typical onset patterns.','Previous immune toxicity and other therapies complicate attribution.'],'**Maintain an accurate treatment history during later presentations.**',['Provide clear discharge and follow-up information.','Investigate new symptoms rather than assigning cause by timing alone.'],[['During therapy','irAE possible'],['After therapy','Delayed irAE possible'],['Attribution','Clinical assessment required']],[IC])

q('A patient has stable ICI-induced hypothyroidism controlled with replacement and no other active toxicity. Which principle is correct?', 'Endocrine replacement alone often permits continuation or resumption of ICI after clinical stabilization',[
 ('Every permanent hormone deficit mandates permanent cessation of ICI','Controlled endocrine deficits differ from many severe inflammatory organ toxicities.'),('High-dose steroids are required indefinitely to replace thyroid hormone','Levothyroxine replaces thyroid hormone; high-dose steroids have a different role.'),('Replacement makes further monitoring unnecessary','Hormone needs and other toxicities require follow-up.')],
 'A controlled endocrine deficit is not the same as ongoing organ inflammation','**Many endocrine irAEs are managed primarily with hormone replacement.**',['Some deficits are long-lasting.','Acute instability or compressive hypophysitis requires a different immediate approach.'],'**Individualize ICI decisions with oncology and endocrinology.**',['Confirm clinical stability and adequate replacement.','Educate patients about stress dosing if adrenal insufficiency is present.'],[['Controlled hypothyroidism','Replacement and monitoring'],['Acute crisis','Stabilize first'],['ICI decision','Individualized, often can continue']],[EN],style='clinical_scenario')

q('A checkpoint-treated patient develops widespread painful blistering skin lesions and mucosal erosions. Which action is most appropriate?', 'Stop the suspected treatment and arrange urgent hospital and dermatology assessment for a severe cutaneous adverse reaction',[
 ('Continue treatment with an emollient alone','Blistering and mucosal involvement are high-risk features.'),('Assume this is uncomplicated acneiform rash','That does not explain severe erosive mucocutaneous disease.'),('Rechallenge immediately to prove causation','Re-exposure can be dangerous in severe cutaneous reactions.')],
 'Mucosal and blistering features change urgency','**Stevens–Johnson syndrome/toxic epidermal necrolysis and other severe reactions require urgent assessment.**',['Review all recent medicines and the differential diagnosis.','Fluid, infection, ocular and pain issues may need specialist care.'],'**Use a severe-reaction pathway and avoid routine rechallenge.**',['Obtain appropriate skin assessment and biopsy when indicated.','Coordinate supportive and immunomodulatory treatment with specialists.'],[['Warning signs','Pain, blistering, mucosa'],['Immediate action','Stop suspected exposure; urgent care'],['Rechallenge','High-risk decision, generally avoided in SJS/TEN']],[IC,ES],style='clinical_scenario')
